import json
from pathlib import Path


def load_payload(path):
    """Read a UTF-8 JSON file whose top-level value is an object or array.

    Invalid JSON, unreadable files, and top-level null/boolean/number/string
    all raise ValueError.
    """
    p = Path(path)
    try:
        text = p.read_text(encoding="utf-8")
    except (OSError, UnicodeError) as exc:
        raise ValueError("cannot read payload file: %s" % (path,)) from exc
    try:
        data = json.loads(text)
    except (json.JSONDecodeError, ValueError) as exc:
        raise ValueError("invalid JSON in payload file: %s" % (path,)) from exc
    if isinstance(data, (dict, list)):
        return data
    raise ValueError("top-level JSON value must be an object or array")

