import math

from model import load_payload  # noqa: F401  (kept for a stable module surface)


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _is_text(value):
    return isinstance(value, str) and value.strip() != ""


def _check_finite(obj):
    """Reject NaN/Infinity anywhere in a nested JSON value."""
    if isinstance(obj, float):
        if not math.isfinite(obj):
            raise ValueError("non-finite numeric value is not allowed")
    elif isinstance(obj, dict):
        for key, value in obj.items():
            _check_finite(key)
            _check_finite(value)
    elif isinstance(obj, list):
        for value in obj:
            _check_finite(value)


def transform(payloads, contract):
    if len(payloads) != 1:
        raise ValueError("notice_coverage expects exactly one payload")
    payload = payloads[0]
    _check_finite(payload)
    if not isinstance(payload, dict):
        raise ValueError("notice_coverage payload must be an object")

    for key in ("clients", "windows", "budget", "cooldown"):
        if key not in payload:
            raise ValueError("missing required field: %s" % key)

    clients_raw = payload["clients"]
    windows_raw = payload["windows"]
    budget = payload["budget"]
    cooldown = payload["cooldown"]

    if not _is_int(budget) or budget < 0:
        raise ValueError("budget must be an int >= 0")
    if not _is_int(cooldown) or cooldown < 0:
        raise ValueError("cooldown must be an int >= 0")

    if not isinstance(clients_raw, list):
        raise ValueError("clients must be a list")
    clients = {}
    for item in clients_raw:
        if not isinstance(item, dict):
            raise ValueError("each client must be an object")
        for key in ("id", "weight", "deadline", "mandatory"):
            if key not in item:
                raise ValueError("client missing required field: %s" % key)
        cid = item["id"]
        weight = item["weight"]
        deadline = item["deadline"]
        mandatory = item["mandatory"]
        if not _is_text(cid):
            raise ValueError("client id must be non-empty text")
        if cid in clients:
            raise ValueError("duplicate client id: %s" % cid)
        if not _is_int(weight) or weight < 0:
            raise ValueError("client weight must be an int >= 0")
        if not _is_int(deadline) or deadline < 0:
            raise ValueError("client deadline must be an int >= 0")
        if not isinstance(mandatory, bool):
            raise ValueError("client mandatory must be a bool")
        clients[cid] = {"weight": weight, "deadline": deadline, "mandatory": mandatory}

    if not isinstance(windows_raw, list):
        raise ValueError("windows must be a list")
    windows = []
    seen_window_ids = set()
    for item in windows_raw:
        if not isinstance(item, dict):
            raise ValueError("each window must be an object")
        for key in ("id", "start", "end", "cost", "clients"):
            if key not in item:
                raise ValueError("window missing required field: %s" % key)
        wid = item["id"]
        start = item["start"]
        end = item["end"]
        cost = item["cost"]
        window_clients = item["clients"]
        if not _is_text(wid):
            raise ValueError("window id must be non-empty text")
        if wid in seen_window_ids:
            raise ValueError("duplicate window id: %s" % wid)
        seen_window_ids.add(wid)
        if not _is_int(start) or start < 0:
            raise ValueError("window start must be an int >= 0")
        if not _is_int(end) or end <= start:
            raise ValueError("window end must be an int > start")
        if not _is_int(cost) or cost < 0:
            raise ValueError("window cost must be an int >= 0")
        if not isinstance(window_clients, list):
            raise ValueError("window clients must be a list")
        seen_clients = set()
        for client_id in window_clients:
            if not _is_text(client_id):
                raise ValueError("window client reference must be non-empty text")
            if client_id in seen_clients:
                raise ValueError("duplicate client in window: %s" % client_id)
            seen_clients.add(client_id)
            if client_id not in clients:
                raise ValueError("unknown client in window: %s" % client_id)
        windows.append(
            {"id": wid, "start": start, "end": end, "cost": cost, "clients": window_clients}
        )

    n = len(windows)
    best = None  # (value, cost, sorted_ids)

    # Brute force all subsets (window count is bounded by 16 by the spec).
    for mask in range(1 << n):
        selected = [i for i in range(n) if (mask >> i) & 1]

        # Mutual non-overlap with cooldown, ordered by time.
        ordered = sorted(selected, key=lambda i: (windows[i]["start"], windows[i]["end"], windows[i]["id"]))
        ok = True
        for a in range(len(ordered) - 1):
            prev = windows[ordered[a]]
            nxt = windows[ordered[a + 1]]
            if prev["end"] + cooldown > nxt["start"]:
                ok = False
                break
        if not ok:
            continue

        total_cost = sum(windows[i]["cost"] for i in selected)
        if total_cost > budget:
            continue

        covered = {}
        for i in selected:
            win = windows[i]
            for client_id in win["clients"]:
                if win["end"] <= clients[client_id]["deadline"]:
                    covered[client_id] = min(covered.get(client_id, win["end"]), win["end"])

        if any(clients[cid]["mandatory"] for cid in clients if cid not in covered):
            continue

        value = sum(clients[cid]["weight"] for cid in covered)
        sorted_ids = sorted(windows[i]["id"] for i in selected)
        candidate = (value, total_cost, sorted_ids)

        if best is None:
            best = candidate
        else:
            bvalue, bcost, bids = best
            if (
                value > bvalue
                or (value == bvalue and total_cost < bcost)
                or (value == bvalue and total_cost == bcost and sorted_ids < bids)
            ):
                best = candidate

    if best is None:
        return {
            "name": contract["name"],
            "result": {
                "feasible": False,
                "selected": [],
                "value": 0,
                "cost": 0,
                "completion": {},
            },
        }

    value, total_cost, sorted_ids = best
    completion = {}
    for win in windows:
        if win["id"] in set(sorted_ids):
            for client_id in win["clients"]:
                if win["end"] <= clients[client_id]["deadline"]:
                    completion[client_id] = min(completion.get(client_id, win["end"]), win["end"])

    return {
        "name": contract["name"],
        "result": {
            "feasible": True,
            "selected": sorted_ids,
            "value": value,
            "cost": total_cost,
            "completion": completion,
        },
    }

