                costs.append(w["cost"] * job["duration"])
        eligible.append(els)
        affinity.append(affs)
        costprod.append(costs)

    # Optimistic upper bound on remaining affinity (ignores capacity).
    suffix_max = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        best_aff = max(affinity[i]) if affinity[i] else 0
        suffix_max[i] = suffix_max[i + 1] + best_aff

    capacities = [w["capacity"] for w in workers]
    durations = [jobs[idx]["duration"] for idx in order]

    # Phase 1: maximum total affinity.
    best_score = -1
    found = False

    def dfs_score(i, score, used):
        nonlocal best_score, found
        if i == n:
            found = True
            if score > best_score:
                best_score = score
            return
        if score + suffix_max[i] < best_score:
            return
        for k, wi in enumerate(eligible[i]):
            dur = durations[i]
            if used[wi] + dur <= capacities[wi]:
                used[wi] += dur
                dfs_score(i + 1, score + affinity[i][k], used)
                used[wi] -= dur

    dfs_score(0, 0, [0] * len(workers))
    if not found:
        return False, 0, 0, []

    target_score = best_score

    # Phase 2: minimum cost among score == target_score.
    INF = float("inf")
    best_cost = INF

    def dfs_cost(i, score, cost, used):
        nonlocal best_cost
        if cost >= best_cost:
            return
        if i == n:
            if score == target_score:
                best_cost = cost
            return
        if score + suffix_max[i] < target_score:
            return
        for k, wi in enumerate(eligible[i]):
            dur = durations[i]
            if used[wi] + dur <= capacities[wi]:
                used[wi] += dur
                dfs_cost(i + 1, score + affinity[i][k], cost + costprod[i][k], used)
                used[wi] -= dur

    dfs_cost(0, 0, 0, [0] * len(workers))

    # Phase 3: lexicographically smallest worker-id vector among optima.
    best_vec = None

    def dfs_vec(i, score, cost, used, vec):
        nonlocal best_vec
        if cost > best_cost:
            return
        if i == n:
            if score == target_score and cost == best_cost:
                if best_vec is None or vec < best_vec:
                    best_vec = vec
            return
        if score + suffix_max[i] < target_score:
            return
        for k, wi in enumerate(eligible[i]):
            dur = durations[i]
            if used[wi] + dur <= capacities[wi]:
                used[wi] += dur
                dfs_vec(i + 1, score + affinity[i][k], cost + costprod[i][k], used, vec + (workers[wi]["id"],))
                used[wi] -= dur

    dfs_vec(0, 0, 0, [0] * len(workers), ())

    assignments = [
        {"job": jobs[order[i]]["id"], "worker": best_vec[i]} for i in range(n)
    ]
    return True, target_score, int(best_cost), assignments


def transform(payloads, contract):
    if not payloads:
        raise ValueError("capacity_assignment expects at least one payload")
    first = payloads[0]
    if not isinstance(first, dict):
        raise ValueError("capacity_assignment first payload must be an object")
    for key in ("jobs", "workers"):
        if key not in first:
            raise ValueError("missing required field: %s" % key)

    jobs_raw = first["jobs"]
    workers_raw = first["workers"]
    if not isinstance(jobs_raw, list):
        raise ValueError("jobs must be a list")
    if not isinstance(workers_raw, list):
        raise ValueError("workers must be a list")

    jobs = []
    seen_job_ids = set()
    for item in jobs_raw:
        if not isinstance(item, dict):
            raise ValueError("each job must be an object")
        for key in ("id", "skill", "duration"):
            if key not in item:
                raise ValueError("job missing required field: %s" % key)
        jid = item["id"]
        skill = item["skill"]
        duration = item["duration"]
        if not _is_text(jid):
            raise ValueError("job id must be non-empty text")
        if jid.strip() in seen_job_ids:
            raise ValueError("duplicate job id: %s" % jid)
        seen_job_ids.add(jid.strip())
        if not _is_text(skill):
            raise ValueError("job skill must be non-empty text")
        if not _is_int(duration) or duration < 1:
            raise ValueError("job duration must be an int >= 1")
        jobs.append({"id": jid, "skill": skill, "duration": duration})

    workers = []
    seen_worker_ids = set()
    for item in workers_raw:
        if not isinstance(item, dict):
            raise ValueError("each worker must be an object")
        for key in ("id", "skills", "capacity", "cost", "affinity"):
            if key not in item:
                raise ValueError("worker missing required field: %s" % key)
        wid = item["id"]
        skills = item["skills"]
        capacity = item["capacity"]
        cost = item["cost"]
        affinity = item["affinity"]
        if not _is_text(wid):
            raise ValueError("worker id must be non-empty text")
        if wid.strip() in seen_worker_ids:
            raise ValueError("duplicate worker id: %s" % wid)
        seen_worker_ids.add(wid.strip())
        if not isinstance(skills, list):
            raise ValueError("worker skills must be a list")
        for skill in skills:
            if not _is_text(skill):
                raise ValueError("worker skill must be non-empty text")
        if not _is_int(capacity) or capacity < 0:
            raise ValueError("worker capacity must be an int >= 0")
        if not _is_int(cost) or cost < 0:
            raise ValueError("worker cost must be an int >= 0")
        if not isinstance(affinity, dict):
            raise ValueError("worker affinity must be an object")
        for _, value in affinity.items():
            if not _is_int(value):
                raise ValueError("affinity values must be ints")
        workers.append(
            {"id": wid, "skills": skills, "capacity": capacity, "cost": cost, "affinity": affinity}
        )

    # Apply optional upstream filtering/capping from subsequent payloads.
    for extra in payloads[1:]:
        res = _unwrap(extra)
        if not isinstance(res, dict):
            raise ValueError("upstream component result must be an object")
        if "selected" in res:
            selected = res["selected"]
            if not isinstance(selected, list):
                raise ValueError("selected must be a list")
            keep = set(selected)
            workers = [w for w in workers if w["id"] in keep]
        if "makespan" in res:
            makespan = res["makespan"]
            if not _is_int(makespan) or makespan < 0:
                raise ValueError("makespan must be an int >= 0")
            for w in workers:
                w["capacity"] = min(w["capacity"], makespan)

    feasible, score, cost, assignments = _solve(jobs, workers)
    return {
        "name": contract["name"],
        "result": {
            "feasible": feasible,
            "score": score,
            "cost": cost,
            "assignments": assignments,
        },
    }

import json
from pathlib import Path


def load_payload(path):
    """Read a UTF-8 JSON file whose top-level value is an object or array."""
    p = Path(path)
    try:
        text = p.read_text(encoding="utf-8")
    except (OSError, UnicodeError) as exc:
        raise ValueError("cannot read payload file: %s" % (path,)) from exc
    try:
        data = json.loads(text)
    except (json.JSONDecodeError, ValueError) as exc:
        raise ValueError("invalid JSON in payload file: %s" % (path,)) from exc
    if isinstance(data, (dict, list)):
        return data
    raise ValueError("top-level JSON value must be an object or array")

