import math

from model import load_payload  # noqa: F401


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _is_text(value):
    return isinstance(value, str) and value.strip() != ""


def _check_finite(obj):
    if isinstance(obj, float):
        if not math.isfinite(obj):
            raise ValueError("non-finite numeric value is not allowed")
    elif isinstance(obj, dict):
        for key, value in obj.items():
            _check_finite(key)
            _check_finite(value)
    elif isinstance(obj, list):
        for value in obj:
            _check_finite(value)


def _unwrap(obj):
    if isinstance(obj, dict) and set(obj.keys()) == {"name", "result"}:
        return obj["result"]
    return obj


def _false_schema(contract):
    return {
        "name": contract["name"],
        "result": {"feasible": False, "makespan": 0, "total_start": 0, "schedule": []},
    }


def _has_cycle(nodes):
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {nid: WHITE for nid in nodes}

    def visit(nid):
        color[nid] = GRAY
        for dep in nodes[nid]["deps"]:
            if color[dep] == GRAY:
                return True
            if color[dep] == WHITE and visit(dep):
                return True
        color[nid] = BLACK
        return False

    for nid in nodes:
        if color[nid] == WHITE:
            if visit(nid):
                return True
    return False


def transform(payloads, contract):
    if len(payloads) != 3:
        raise ValueError("resource_cutover expects exactly three payloads")
    for payload in payloads:
        _check_finite(payload)

    local = payloads[0]
    if not isinstance(local, dict):
        raise ValueError("resource_cutover local payload must be an object")
    for key in ("nodes", "capacity", "horizon"):
        if key not in local:
            raise ValueError("missing required field: %s" % key)

    nodes_raw = local["nodes"]
    capacity = local["capacity"]
    horizon = local["horizon"]

    if not isinstance(nodes_raw, list):
        raise ValueError("nodes must be a list")
    if not _is_int(capacity) or capacity < 1:
        raise ValueError("capacity must be an int >= 1")
    if not _is_int(horizon) or horizon < 0:
        raise ValueError("horizon must be an int >= 0")

    nodes = {}
    for item in nodes_raw:
        if not isinstance(item, dict):
            raise ValueError("each node must be an object")
        for key in ("id", "client", "duration", "demand", "deps"):
            if key not in item:
                raise ValueError("node missing required field: %s" % key)
        nid = item["id"]
        client = item["client"]
        duration = item["duration"]
        demand = item["demand"]
        deps = item["deps"]
        if not _is_text(nid):
            raise ValueError("node id must be non-empty text")
        if not _is_text(client):
            raise ValueError("node client must be non-empty text")
        if not _is_int(duration) or duration < 1:
            raise ValueError("node duration must be an int >= 1")
        if not _is_int(demand) or demand < 1:
            raise ValueError("node demand must be an int >= 1")
        if not isinstance(deps, list):
            raise ValueError("node deps must be a list")
        for dep in deps:
            if not _is_text(dep):
                raise ValueError("node dependency id must be non-empty text")
        if nid in nodes:
            raise ValueError("duplicate node id: %s" % nid)
        nodes[nid] = {
            "id": nid,
            "client": client,
            "duration": duration,
            "demand": demand,
            "deps": deps,
        }

    for nid, node in nodes.items():
        for dep in node["deps"]:
            if dep not in nodes:
                raise ValueError("unknown dependency: %s" % dep)
    if _has_cycle(nodes):
        raise ValueError("dependency cycle detected")

    notice = _unwrap(payloads[1])
    assign = _unwrap(payloads[2])
    if not isinstance(notice, dict):
        raise ValueError("notice_coverage result must be an object")
    if not isinstance(assign, dict):
        raise ValueError("capacity_assignment result must be an object")
    if "feasible" not in notice or not isinstance(notice["feasible"], bool):
        raise ValueError("notice result must contain a boolean feasible field")
    if "feasible" not in assign or not isinstance(assign["feasible"], bool):
        raise ValueError("assignment result must contain a boolean feasible field")

    if not notice["feasible"] or not assign["feasible"]:
        return _false_schema(contract)

    if not nodes:
        return {
            "name": contract["name"],
            "result": {"feasible": True, "makespan": 0, "total_start": 0, "schedule": []},
        }

    if "completion" not in notice:
        raise ValueError("notice result missing completion")
    completion = notice["completion"]
    if not isinstance(completion, dict):
        raise ValueError("notice completion must be an object")
    for client, end in completion.items():
        if not _is_int(end) or end < 0:
            raise ValueError("notice completion values must be ints >= 0")

    if "assignments" not in assign:
        raise ValueError("assignment result missing assignments")
    assignments_raw = assign["assignments"]
    if not isinstance(assignments_raw, list):
        raise ValueError("assignments must be a list")
    worker_of = {}
    for a in assignments_raw:
        if not isinstance(a, dict):
            raise ValueError("each assignment must be an object")
        if "job" not in a or "worker" not in a:
            raise ValueError("assignment missing job or worker")
        job = a["job"]
        worker = a["worker"]
        if not _is_text(job):
            raise ValueError("assignment job must be non-empty text")
        if not _is_text(worker):
            raise ValueError("assignment worker must be non-empty text")
        if job in worker_of and worker_of[job] != worker:
            raise ValueError("conflicting assignment for job: %s" % job)
        worker_of[job] = worker

    release = {}
    for nid, node in nodes.items():
        if node["client"] not in completion:
            return _false_schema(contract)
        if node["id"] not in worker_of:
            return _false_schema(contract)
        if node["demand"] > capacity:
            return _false_schema(contract)
        release[nid] = completion[node["client"]]

    # Exact serial-schedule enumeration: try every precedence-feasible order and
    # place each node at its earliest feasible integer start.
    sorted_ids = sorted(nodes.keys())
    successors = {nid: [] for nid in nodes}
    for nid, node in nodes.items():
        for dep in node["deps"]:
            successors[dep].append(nid)

    best = None  # (makespan, total_start, start_vector)

    def dfs(scheduled, starts, ends, demand_at, worker_end, makespan, total):
        nonlocal best
        if len(scheduled) == len(nodes):
            vector = tuple(starts[nid] for nid in sorted_ids)
            candidate = (makespan, total, vector)
            if best is None or candidate < best:
                best = candidate
            return

        if best is not None:
            if makespan > best[0]:
                return
            if makespan == best[0] and total > best[1]:
                return

        for nid in sorted_ids:
            if nid in scheduled:
                continue
            node = nodes[nid]
            if any(dep not in scheduled for dep in node["deps"]):
                continue

            lower = release[nid]
            for dep in node["deps"]:
                if ends[dep] > lower:
                    lower = ends[dep]
            worker = worker_of[node["id"]]
            if worker_end.get(worker, 0) > lower:
                lower = worker_end.get(worker, 0)

            duration = node["duration"]
            demand = node["demand"]
            start = None
            t = lower
            while t + duration <= horizon:
                feasible_slot = True
                for slot in range(t, t + duration):
                    if demand_at.get(slot, 0) + demand > capacity:
                        feasible_slot = False
                        break
                if feasible_slot:
                    start = t
                    break
                t += 1
            if start is None:
                continue

            end = start + duration
            starts[nid] = start
            ends[nid] = end
            for slot in range(start, end):
                demand_at[slot] = demand_at.get(slot, 0) + demand
            previous_worker_end = worker_end.get(worker)
            worker_end[worker] = max(previous_worker_end or 0, end)

            dfs(
                scheduled | {nid},
                starts,
                ends,
                demand_at,
                worker_end,
                max(makespan, end),
                total + start,
            )

            del starts[nid]
            del ends[nid]
            for slot in range(start, end):
                demand_at[slot] -= demand
                if demand_at[slot] == 0:
                    del demand_at[slot]
            if previous_worker_end is None:
                del worker_end[worker]
            else:
                worker_end[worker] = previous_worker_end

    dfs(set(), {}, {}, {}, {}, 0, 0)

    if best is None:
        return _false_schema(contract)

    makespan, total_start, vector = best
    schedule = []
    for idx, nid in enumerate(sorted_ids):
        schedule.append(
            {
                "id": nid,
                "start": vector[idx],
                "end": vector[idx] + nodes[nid]["duration"],
                "worker": worker_of[node["id"]] if nid in nodes else None,
            }
        )
    # worker_of uses node id (== nid) for the mapped job.
    schedule = [
        {
            "id": nid,
            "start": vector[idx],
            "end": vector[idx] + nodes[nid]["duration"],
            "worker": worker_of[nodes[nid]["id"]],
        }
        for idx, nid in enumerate(sorted_ids)
    ]

    return {
        "name": contract["name"],
        "result": {
            "feasible": True,
            "makespan": makespan,
            "total_start": total_start,
            "schedule": schedule,
        },
    }

