def component_contracts():
    return sorted(
        p
        for p in ROOT.rglob("contract.json")
        if "outputs" not in p.relative_to(ROOT).parts
    )


def load_contract(path):
    return json.loads(path.read_text(encoding="utf-8"))


def main():
    contracts = component_contracts()
    if not contracts:
        raise ValueError("no component contracts found")

    by_output = {}
    for path in contracts:
        contract = load_contract(path)
        key = str(ROOT / contract["output"])
        if key in by_output:
            raise ValueError("duplicate component output: %s" % contract["output"])
        by_output[key] = path

    dependencies = {}
    for path in contracts:
        contract = load_contract(path)
        deps = []
        for inp in contract["inputs"]:
            key = str(ROOT / inp)
            if key in by_output and by_output[key] != path:
                deps.append(by_output[key])
        dependencies[path] = deps

    indegree = {path: len(dependencies[path]) for path in contracts}
    dependents = {path: [] for path in contracts}
    for path, deps in dependencies.items():
        for dep in deps:
            dependents[dep].append(path)

    order = []
    ready = [p for p in contracts if indegree[p] == 0]
    ready.sort(key=lambda p: str(p.relative_to(ROOT)))
    while ready:
        path = ready.pop(0)
        order.append(path)
        for nxt in sorted(dependents[path], key=lambda p: str(p.relative_to(ROOT))):
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                ready.append(nxt)
                ready.sort(key=lambda p: str(p.relative_to(ROOT)))

