import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def _write_json(path, data):
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(
        json.dumps(data, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n",
        encoding="utf-8",
    )


def _is_false(value):
    return value is False


def _is_true(value):
    return value is True


def _number(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def main():
    manifest_path = ROOT / "outputs" / "core_manifest.json"
    core_object = json.loads(manifest_path.read_text(encoding="utf-8"))
    if not isinstance(core_object, dict) or "components" not in core_object:
        raise ValueError("core_manifest must be an object with a components key")
    components = core_object["components"]
    if not isinstance(components, dict):
        raise ValueError("core_manifest components must be an object")

    component_count = len(components)

    attention = []
    for name in sorted(components):
        result = components[name]
        if not isinstance(result, dict):
            continue
        included = False
        if "blocked" in result and _is_true(result["blocked"]):
            included = True
        elif "feasible" in result and _is_false(result["feasible"]):
            included = True
        elif "compatible" in result and _is_false(result["compatible"]):
            included = True
        elif "deny" in result and _number(result["deny"]) and result["deny"] > 0:
            included = True
        elif "score_total" in result and _number(result["score_total"]) and result["score_total"] >= 20:
            included = True
        if included:
            attention.append(name)

    compact = json.dumps(
        core_object,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")
    sha256 = hashlib.sha256(compact).hexdigest()

    report = {
        "title": "API 下线管理",
        "component_count": component_count,
        "sha256": sha256,
        "attention": attention,
    }
    _write_json(ROOT / "outputs" / "final_report.json", report)


if __name__ == "__main__":
    main()

